119	    /**
120	     * Displays a prompt and reads a password from STDIN without echoing input.
121	     *
122	     * On Unix-like systems `stty -echo` is used to suppress character echo.
123	     * On Windows (or when stty is unavailable) input is read with echo visible
124	     * and a warning is displayed to the user.
125	     *
126	     * @param string $label   The label to display before the input cursor.
127	     * @param string $default The value to use when the user provides no input.
128	     * @return string The trimmed user input, or $default when input is empty.
129	     */
130	    function promptPassword(string $label, string $default = '') : string
131	    {
132	        $sttyAvailable = (DIRECTORY_SEPARATOR !== '\\')
133	            && (shell_exec('stty 2>/dev/null; echo $?') !== null);
134	
135	        if ($default !== '')
136	        {
137	            echo $label . ' [' . str_repeat('*', min(8, strlen($default))) . ']: ';
138	        }
139	        else
140	        {
141	            echo $label . ': ';
142	        }
143	
144	        if ($sttyAvailable)
145	        {
146	            shell_exec('stty -echo');
147	            $input = fgets(STDIN);
148	            shell_exec('stty echo');
149	            echo PHP_EOL;
150	        }
151	        else
152	        {
153	            writeln('(warning: password will be visible — stty not available)');
154	            $input = fgets(STDIN);
155	        }
156	
157	        if ($input === false)
158	        {
159	            return $default;
160	        }
161	
162	        $trimmed = trim($input);
163	
164	        if ($trimmed === '')
165	        {
166	            return $default;
167	        }
168	
169	        return $trimmed;
170	    }
